cat << 'EOF' > /app/output/style.css
:root {
  --primary: #4F46E5; /* Indigo */
  --primary-hover: #4338CA;
  --accent: #8B5CF6; /* Purple */
  --blue: #1868DB;
  --orange: #FF613D;
  --text-dark: #292A2E;
  --text-gray: #4B5563;
  --text-light: #6B7280;
  --bg-light: #F8FAFC;
  --white: #FFFFFF;
  --border: #E2E8F0;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
  --nav-height: 72px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  color: var(--text-dark);
  line-height: 1.5;
  background-color: var(--white);
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color 0.2s;
}
a:hover {
  color: var(--primary-hover);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-dark);
  margin-bottom: 1rem;
}
h1 { font-size: 3.5rem; letter-spacing: -0.02em; }
h2 { font-size: 2.5rem; letter-spacing: -0.01em; }
h3 { font-size: 1.5rem; }
p { margin-bottom: 1rem; color: var(--text-gray); }

.subtitle {
  font-size: 1.25rem;
  color: var(--text-gray);
  margin-bottom: 2rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.2s;
  border: 1px solid transparent;
  text-align: center;
}
.btn-primary {
  background-color: var(--primary);
  color: var(--white);
}
.btn-primary:hover {
  background-color: var(--primary-hover);
  color: var(--white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}
.btn-secondary {
  background-color: var(--bg-light);
  color: var(--text-dark);
  border-color: var(--border);
}
.btn-secondary:hover {
  background-color: var(--border);
  color: var(--text-dark);
}
.btn-outline {
  background-color: transparent;
  color: var(--text-dark);
  border-color: var(--border);
}
.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
}
.btn-block {
  width: 100%;
}

/* Navigation */
.navbar {
  position: sticky;
  top: 0;
  background-color: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
  z-index: 100;
  height: var(--nav-height);
  display: flex;
  align-items: center;
}
.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
}
.nav-logo {
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
}
.nav-links a {
  color: var(--text-dark);
  font-weight: 500;
}
.nav-links a:hover {
  color: var(--primary);
}
.nav-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
}

/* Sections */
section {
  padding: 5rem 0;
}
.section-light {
  background-color: var(--bg-light);
}

/* Hero */
.hero {
  padding: 8rem 0 6rem;
  text-align: center;
  background: linear-gradient(135deg, #F8FAFC 0%, #EEF2FF 100%);
}
.hero h1 {
  max-width: 800px;
  margin: 0 auto 1.5rem;
  background: linear-gradient(to right, var(--primary), var(--accent));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.hero p {
  max-width: 600px;
  margin: 0 auto 2.5rem;
  font-size: 1.25rem;
}
.hero-ctas {
  display: flex;
  gap: 1rem;
  justify-content: center;
}
.hero-mockup {
  margin-top: 4rem;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  background: white;
  padding: 1rem;
}

/* Logo Bar */
.logo-bar {
  padding: 3rem 0;
  border-bottom: 1px solid var(--border);
  text-align: center;
}
.logo-bar p {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-light);
  margin-bottom: 1.5rem;
}
.logos {
  display: flex;
  justify-content: center;
  gap: 3rem;
  flex-wrap: wrap;
  align-items: center;
  opacity: 0.6;
}
.logos span {
  font-size: 1.25rem;
  font-weight: 700;
}

/* Grid Layouts */
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}
.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

/* Cards */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s, box-shadow 0.2s;
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

/* Pricing Toggle */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}
.toggle-switch {
  position: relative;
  width: 60px;
  height: 32px;
  background: var(--border);
  border-radius: 32px;
  cursor: pointer;
  transition: 0.3s;
}
.toggle-switch.active {
  background: var(--primary);
}
.toggle-slider {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 24px;
  height: 24px;
  background: white;
  border-radius: 50%;
  transition: 0.3s;
}
.toggle-switch.active .toggle-slider {
  transform: translateX(28px);
}
.badge {
  background-color: var(--bg-light);
  color: var(--primary);
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
  border: 1px solid var(--border);
}

/* Pricing Cards */
.pricing-card {
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  position: relative;
  display: flex;
  flex-direction: column;
}
.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}
.popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
}
.price {
  font-size: 3rem;
  font-weight: 800;
  margin: 1rem 0;
  display: flex;
  align-items:baseline;
}
.price span {
  font-size: 1rem;
  color: var(--text-light);
  font-weight: 400;
  margin-left: 0.25rem;
}
.pricing-features {
  list-style: none;
  margin: 2rem 0;
  flex-grow: 1;
}
.pricing-features li {
  margin-bottom: 0.75rem;
  padding-left: 1.5rem;
  position: relative;
  color: var(--text-gray);
  font-size: 0.9rem;
}
.pricing-features li::before {
  content: '✓';
  color: var(--primary);
  position: absolute;
  left: 0;
  font-weight: bold;
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  padding: 1.5rem 0;
  font-weight: 600;
  font-size: 1.125rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-question::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--primary);
}
.faq-item.active .faq-question::after {
  content: '−';
}
.faq-answer {
  padding-bottom: 1.5rem;
  display: none;
  color: var(--text-gray);
}
.faq-item.active .faq-answer {
  display: block;
}

/* Table */
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
}
.comparison-table th, .comparison-table td {
  padding: 1rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
.comparison-table th {
  background: var(--bg-light);
  font-weight: 600;
}
.comparison-table tr:hover td {
  background: var(--bg-light);
}

/* Auth Pages */
.auth-layout {
  display: flex;
  min-height: 100vh;
}
.auth-form-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 2rem;
}
.auth-form {
  width: 100%;
  max-width: 400px;
}
.auth-sidebar {
  flex: 1;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  color: white;
  display: none;
  flex-direction: column;
  justify-content: center;
  padding: 4rem;
}
@media (min-width: 768px) {
  .auth-sidebar { display: flex; }
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0.75rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  margin-bottom: 0.75rem;
  background: white;
  cursor: pointer;
  font-weight: 500;
  transition: background 0.2s;
}
.social-btn:hover { background: var(--bg-light); }
.divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 1.5rem 0;
  color: var(--text-light);
}
.divider::before, .divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--border);
}
.divider:not(:empty)::before { margin-right: 0.5rem; }
.divider:not(:empty)::after { margin-left: 0.5rem; }

.form-group { margin-bottom: 1.5rem; }
.form-control {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color 0.2s;
}
.form-control:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px rgba(79, 70, 229, 0.2);
}

/* Footer */
footer {
  background: var(--white);
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}
@media (min-width: 768px) {
  .footer-grid { grid-template-columns: repeat(6, 1fr); }
}
.footer-col h4 {
  font-size: 0.875rem;
  text-transform: uppercase;
  color: var(--text-dark);
  margin-bottom: 1.5rem;
}
.footer-col ul {
  list-style: none;
}
.footer-col li { margin-bottom: 0.75rem; }
.footer-col a {
  color: var(--text-gray);
  font-size: 0.875rem;
}
.footer-col a:hover { color: var(--primary); }

/* Banner / Cookie */
.cookie-banner {
  position: fixed;
  bottom: 1rem;
  left: 1rem;
  right: 1rem;
  background: var(--white);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-width: 800px;
  margin: 0 auto;
}
@media (min-width: 768px) {
  .cookie-banner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}
.cookie-modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  display: none;
  place-items: center;
  z-index: 1001;
}
.cookie-modal.active { display: grid; }
.cookie-modal-content {
  background: white;
  padding: 2rem;
  border-radius: var(--radius-lg);
  max-width: 500px;
  width: 90%;
}
.toggle-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 0;
  border-bottom: 1px solid var(--border);
}

.cta-banner {
  background: linear-gradient(135deg, var(--primary), var(--accent));
  color: white;
  text-align: center;
  padding: 4rem 1.5rem;
  border-radius: var(--radius-xl);
  margin: 4rem 1.5rem;
}
.cta-banner h2 { color: white; }

/* slider */
.slider-container {
  margin: 2rem 0;
}
input[type=range] {
  width: 100%;
  cursor: pointer;
}
EOF

cat << 'EOF' > /app/output/script.js
document.addEventListener('DOMContentLoaded', () => {

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    if(question) {
      question.addEventListener('click', () => {
        item.classList.toggle('active');
      });
    }
  });

  // Pricing Toggle
  const billingToggle = document.getElementById('billingToggle');
  if(billingToggle) {
    billingToggle.addEventListener('click', () => {
      billingToggle.classList.toggle('active');
      const isAnnual = billingToggle.classList.contains('active');

      const prices = document.querySelectorAll('.dynamic-price');
      prices.forEach(p => {
        const monthly = p.getAttribute('data-monthly');
        const annual = p.getAttribute('data-annual');
        if(monthly && annual) {
          p.textContent = isAnnual ? annual : monthly;
        }
      });
    });
  }

  // Team Size Slider
  const teamSlider = document.getElementById('teamSizeSlider');
  const teamSizeVal = document.getElementById('teamSizeVal');
  if(teamSlider && teamSizeVal) {
    teamSlider.addEventListener('input', (e) => {
      teamSizeVal.textContent = e.target.value;
      // Simple logic to highlight recommended plan
      const cards = document.querySelectorAll('.pricing-card');
      cards.forEach(c => c.classList.remove('popular'));
      if(e.target.value > 100) {
        document.getElementById('plan-enterprise')?.classList.add('popular');
      } else if(e.target.value > 20) {
        document.getElementById('plan-business-ai')?.classList.add('popular');
      } else {
        document.getElementById('plan-business')?.classList.add('popular');
      }
    });
  }

  // Comparison Expand
  const expandBtns = document.querySelectorAll('.expand-features-btn');
  expandBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const targetId = btn.getAttribute('data-target');
      const target = document.getElementById(targetId);
      if(target) {
        if(target.style.display === 'none' || !target.style.display) {
          target.style.display = 'block';
          btn.textContent = 'Hide features';
        } else {
          target.style.display = 'none';
          btn.textContent = 'See all features';
        }
      }
    });
  });

  // Cookie Consent
  const cookieBanner = document.getElementById('cookieBanner');
  const acceptBtn = document.getElementById('acceptCookies');
  const rejectBtn = document.getElementById('rejectCookies');
  const manageBtn = document.getElementById('manageCookies');
  const cookieModal = document.getElementById('cookieModal');
  const closeCookieModal = document.getElementById('closeCookieModal');

  if(cookieBanner && !localStorage.getItem('cookieConsent')) {
    cookieBanner.style.display = 'flex';
  } else if(cookieBanner) {
    cookieBanner.style.display = 'none';
  }

  if(acceptBtn) {
    acceptBtn.addEventListener('click', () => {
      localStorage.setItem('cookieConsent', 'accepted');
      cookieBanner.style.display = 'none';
    });
  }
  if(rejectBtn) {
    rejectBtn.addEventListener('click', () => {
      localStorage.setItem('cookieConsent', 'rejected');
      cookieBanner.style.display = 'none';
    });
  }
  if(manageBtn && cookieModal) {
    manageBtn.addEventListener('click', () => {
      cookieModal.classList.add('active');
    });
  }
  if(closeCookieModal) {
    closeCookieModal.addEventListener('click', () => {
      cookieModal.classList.remove('active');
      localStorage.setItem('cookieConsent', 'managed');
      if(cookieBanner) cookieBanner.style.display = 'none';
    });
  }

  // Auth Forms
  const authForms = document.querySelectorAll('.auth-form form');
  authForms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      // Mock proceed
      alert("Proceeding to authentication flow...");
      window.location.href = 'index.html';
    });
  });

});
EOF
